import { Object3D, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import {
	MeshBasicNodeMaterial,
	texture as texNode,
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';

/**
 * @typedef {Object} NodeConfig
 * @property {{ imageUrl?: string }} assets
 * @property {{ cinematicPrimitives?: Array<{ name: string, params: any }> }} cinematicPrimitives
 * @property {{ position?: [number, number, number], rotation?: [number, number, number], scale?: [number, number, number] }} transform
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url: string) => any} textureLoader
 * @property {{ [key: string]: (obj: Object3D, params: any) => void }} primitives
 */

/**
 * Creates a textured plane node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
	const root = new ObjectD3 ? new Object3D() : new Object3D(); // fallback safety

	// Apply transform
	if (config.transform?.position) {
		root.position.set(...config.transform.position);
	}
	if (config.transform?.rotation) {
		const [rx, ry, rz] = config.transform.rotation;
		root.rotation.set(rx, ry, rz);
	}
	if (config.transform?.scale) {
		root.scale.set(...config.transform.scale);
	}

	// Load texture (synchronous via cached loader)
	const tex = config.assets?.imageUrl ? ctx.textureLoader(config.assets.imageUrl) : null;

	// Plane geometry (unit size)
	const geometry = new PlaneGeometry(1, 1);
	// Material – basic node material with optional map
	const material = new MeshBasicNodeMaterial({
		map: tex ? texNode(tex) : null,
		color: new Color(0xffffff),
	});

	const mesh = new Mesh(geometry, material);
	root.add(mesh);

	// Apply cinematic primitives if any
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		}
	}

	// Handlers placeholder (no interactions defined)
	root.userData.handlers = {};

	// Cleanup method
	root.userData.cleanup = () => {
		// Dispose three.js resources
		geometry.dispose();
		material.dispose();
		if (tex && typeof tex.dispose === 'function') {
			tex.dispose();
		}
		// Kill any GSAP tweens/timelines attached to this node
		gsap.killTweensOf(mesh);
		gsap.globalTimeline.clear();
	};

	return root;
}
